const input = $input.first()?.json ?? {};
const source = input.query ?? input;
const headers = source.headers ?? input.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const deriveBaseUrl = (headers, fallback) => {
  const forwardedProto = clean(headers['x-forwarded-proto']);
  const forwardedHost = clean(headers['x-forwarded-host']);
  const host = forwardedHost || clean(headers.host);
  const forwardedPort = clean(headers['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefaultPort = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefaultPort) authority = `${authority}:${forwardedPort}`;
  }
  return `${proto}://${authority}`;
};
const sqlLiteral = (value) => `'${String(value).replace(/'/g, "''")}'`;
const rawBatchId = clean(source.batch_id ?? source.batchId);
const rawItemId = clean(source.item_id ?? source.itemId ?? source.id);
const parsedBatchId = Number.parseInt(rawBatchId, 10);
const parsedItemId = Number.parseInt(rawItemId, 10);
const confirmCancel = ['1', 'true', 'yes', 'cancel'].includes(clean(source.confirm ?? source.confirmed).toLowerCase());
const fallbackBaseUrl = 'http://n8n:5678';
const n8nBaseUrl = deriveBaseUrl(headers, fallbackBaseUrl);
if (!Number.isInteger(parsedBatchId) || parsedBatchId <= 0 || !Number.isInteger(parsedItemId) || parsedItemId <= 0) {
  return [{
    json: {
      batch_id: rawBatchId,
      item_id: rawItemId,
      confirm_cancel: confirmCancel,
      response_code: 400,
      n8n_base_url: n8nBaseUrl,
      sql: "SELECT NULL::bigint AS batch_id, NULL::bigint AS item_id, false AS item_exists, false AS can_cancel, ''::text AS batch_status, false AS confirm_cancel, false AS cancelled, NULL::text AS member, NULL::text AS source_membership, NULL::text AS target_membership, NULL::text AS status, NULL::text AS notes, NULL::timestamptz AS created_at, NULL::text AS export_file_name;"
    }
  }];
}
const sql = `
WITH requested AS (
  SELECT
    ${sqlLiteral(parsedBatchId)}::bigint AS batch_id,
    ${sqlLiteral(parsedItemId)}::bigint AS item_id,
    ${confirmCancel ? 'true' : 'false'} AS confirm_cancel
),
target AS (
  SELECT
    q.id AS item_id,
    q.batch_id,
    q.member,
    q.source_membership,
    q.target_membership,
    q.status,
    q.notes,
    q.created_at,
    q.export_file_name,
    b.status AS batch_status
  FROM public.signup_batch_clubspark_import_items q
  JOIN public.signup_batches b
    ON b.id = q.batch_id
  JOIN requested r
    ON r.batch_id = q.batch_id
   AND r.item_id = q.id
),
cancelled AS (
  UPDATE public.signup_batch_clubspark_import_items q
  SET status = 'cancelled'
  FROM target t, requested r
  WHERE r.confirm_cancel = true
    AND t.batch_status = 'Processing'
    AND t.status NOT IN ('cancelled', 'imported')
    AND q.id = t.item_id
    AND q.batch_id = t.batch_id
  RETURNING
    q.id AS item_id,
    q.batch_id,
    q.member,
    q.source_membership,
    q.target_membership,
    q.status,
    q.notes,
    q.created_at,
    q.export_file_name,
    t.batch_status
)
SELECT
  r.batch_id,
  r.item_id,
  (COALESCE(t.item_id, c.item_id) IS NOT NULL) AS item_exists,
  COALESCE(t.batch_status, c.batch_status, '') AS batch_status,
  (COALESCE(t.item_id, c.item_id) IS NOT NULL AND COALESCE(t.batch_status, c.batch_status) = 'Processing' AND COALESCE(t.status, c.status) NOT IN ('cancelled', 'imported')) AS can_cancel,
  r.confirm_cancel,
  (c.item_id IS NOT NULL) AS cancelled,
  COALESCE(c.member, t.member) AS member,
  COALESCE(c.source_membership, t.source_membership) AS source_membership,
  COALESCE(c.target_membership, t.target_membership) AS target_membership,
  COALESCE(c.status, t.status) AS status,
  COALESCE(c.notes, t.notes) AS notes,
  COALESCE(c.created_at, t.created_at) AS created_at,
  COALESCE(c.export_file_name, t.export_file_name) AS export_file_name
FROM requested r
LEFT JOIN target t ON true
LEFT JOIN cancelled c ON true;`;
return [{
  json: {
    batch_id: parsedBatchId,
    item_id: parsedItemId,
    confirm_cancel: confirmCancel,
    response_code: 200,
    n8n_base_url: n8nBaseUrl,
    sql
  }
}];

const source = $('Build Cancel Query').first()?.json ?? {};
const row = $input.first()?.json ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const escapeHtml = (value) => clean(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const formatDateTime = (value) => {
  const raw = clean(value);
  if (!raw) return 'Not available';
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw;
  return date.toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' });
};
const batchId = clean(row.batch_id || source.batch_id);
const itemId = clean(row.item_id || source.item_id);
const targetMembership = clean(row.target_membership);
const n8nBaseUrl = clean(source.n8n_base_url) || 'http://n8n:5678';
const reviewUrlBase = `${n8nBaseUrl}/webhook/clubspark-package-import-queue-review?batch_id=${encodeURIComponent(batchId)}`;
const reviewUrl = targetMembership ? `${reviewUrlBase}&target_membership=${encodeURIComponent(targetMembership)}&_ts=${Date.now()}` : `${reviewUrlBase}&_ts=${Date.now()}`;
const selfUrl = `${n8nBaseUrl}/webhook/cancel-clubspark-package-import-item`;
const itemExists = row.item_exists === true || clean(row.item_exists).toLowerCase() === 'true';
const canCancel = row.can_cancel === true || clean(row.can_cancel).toLowerCase() === 'true';
const confirmCancel = row.confirm_cancel === true || clean(source.confirm_cancel).toLowerCase() === 'true';
const cancelled = row.cancelled === true || clean(row.cancelled).toLowerCase() === 'true';
const batchStatus = clean(row.batch_status) || 'Unknown';
const responseCode = !itemExists ? 404 : confirmCancel && !cancelled ? 409 : 200;
const details = [
  ['Batch', batchId],
  ['Queue Item', itemId],
  ['Queued', formatDateTime(row.created_at)],
  ['Member', row.member],
  ['Current Package', row.source_membership],
  ['Target Package', row.target_membership],
  ['Status', row.status],
  ['Export File', row.export_file_name],
  ['Notes', row.notes]
].filter(([, value]) => clean(value) !== '' && clean(value) !== 'Not available');
const detailHtml = details.map(([label, value]) => `<div class="detail"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join('');
let badge = 'Action needed';
let badgeClass = 'badge warning';
let title = 'Cancel ClubSpark Package Queue Item';
let message = 'Review the queued package-import row below before cancelling it.';
let actionHtml = `<form method="get" action="${selfUrl}"><input type="hidden" name="batch_id" value="${escapeHtml(batchId)}"><input type="hidden" name="item_id" value="${escapeHtml(itemId)}"><input type="hidden" name="confirm" value="1"><div class="actions"><button class="button danger" type="submit">Cancel Queue Item</button><a class="button secondary" href="${reviewUrl}">Back to Queue Review</a><button type="button" class="button secondary" onclick="window.close()">Close</button></div></form>`;
if (!itemExists) {
  badge = 'Not found';
  badgeClass = 'badge error';
  title = 'Queue Item Not Found';
  message = 'The requested ClubSpark package queue row no longer exists for this batch.';
  actionHtml = `<div class="actions"><a class="button secondary" href="${reviewUrl}">Back to Queue Review</a><button type="button" class="button secondary" onclick="window.close()">Close</button></div>`;
} else if (!canCancel) {
  badge = 'Locked';
  badgeClass = 'badge error';
  title = 'Cancellation Not Available';
  message = clean(row.status) === 'imported'
    ? 'Imported queue rows are locked. Add a dedicated reset action if you need to reopen them later.'
    : clean(row.status) === 'cancelled'
      ? 'This queue row is already cancelled.'
      : `Queue rows can only be changed while the batch is Processing. Current batch status: ${batchStatus}.`;
  actionHtml = `<div class="actions"><a class="button secondary" href="${reviewUrl}">Back to Queue Review</a><button type="button" class="button secondary" onclick="window.close()">Close</button></div>`;
} else if (cancelled) {
  badge = 'Cancelled';
  badgeClass = 'badge success';
  title = 'Queue Item Cancelled';
  message = 'The ClubSpark package queue row was marked as cancelled and will no longer be picked up for export.';
  actionHtml = `<div class="actions"><a class="button secondary" href="${reviewUrl}">Back to Queue Review</a><button type="button" class="button secondary" onclick="window.close()">Close</button></div>`;
} else if (confirmCancel) {
  badge = 'Action needed';
  badgeClass = 'badge error';
  title = 'Cancellation Did Not Complete';
  message = 'The cancel request did not complete. Reload the queue review page and try again.';
  actionHtml = `<div class="actions"><a class="button secondary" href="${reviewUrl}">Back to Queue Review</a><button type="button" class="button secondary" onclick="window.close()">Close</button></div>`;
}
const warningMessage = 'Cancellation keeps the queue history but removes this row from the active export set. Use this when the member should not be included in the next ClubSpark workbook.';
const html = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f7f8fc;
      --panel: #ffffff;
      --ink: #2e3d4e;
      --muted: #6b7785;
      --line: #e2e8f0;
      --accent: #509ee3;
      --danger: #b42318;
      --danger-soft: #fef3f2;
      --success: #166534;
      --success-soft: #ecfdf3;
      --warning: #9a6700;
      --warning-soft: #fff7ed;
      --button-soft: #eef2f7;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      padding: 24px;
      font-family: Lato, 'Helvetica Neue', Arial, sans-serif;
      color: var(--ink);
      background: linear-gradient(180deg, #fbfcfe 0%, var(--bg) 100%);
    }
    .panel {
      max-width: 820px;
      margin: 0 auto;
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 18px;
      padding: 28px;
      box-shadow: 0 18px 40px rgba(53, 72, 91, 0.08);
    }
    .badge {
      display: inline-flex;
      padding: 6px 12px;
      border-radius: 999px;
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }
    .badge.warning { color: var(--warning); background: var(--warning-soft); }
    .badge.error { color: var(--danger); background: var(--danger-soft); }
    .badge.success { color: var(--success); background: var(--success-soft); }
    h1 {
      margin: 16px 0 8px;
      font-size: 32px;
      line-height: 1.1;
    }
    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
      font-size: 16px;
    }
    .warning-box {
      margin-top: 18px;
      padding: 16px 18px;
      border-radius: 14px;
      border: 1px solid #fecdca;
      background: var(--danger-soft);
      color: var(--danger);
      font-weight: 700;
      line-height: 1.5;
    }
    .details {
      display: grid;
      gap: 12px;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      margin-top: 24px;
    }
    .detail {
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 14px 16px;
      background: #f8fafc;
    }
    .detail span {
      display: block;
      margin-bottom: 6px;
      color: var(--muted);
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }
    .detail strong {
      font-size: 17px;
      line-height: 1.4;
      word-break: break-word;
    }
    .actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
      margin-top: 24px;
    }
    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 12px 18px;
      border-radius: 999px;
      font: inherit;
      font-weight: 700;
      text-decoration: none;
      border: 0;
      cursor: pointer;
    }
    .button.danger {
      color: #fff;
      background: linear-gradient(135deg, var(--danger) 0%, #912018 100%);
      box-shadow: 0 10px 24px rgba(180, 35, 24, 0.22);
    }
    .button.secondary {
      color: var(--ink);
      background: var(--button-soft);
      border: 1px solid var(--line);
    }
  </style>
</head>
<body>
  <main class="panel">
    <span class="${badgeClass}">${escapeHtml(badge)}</span>
    <h1>${escapeHtml(title)}</h1>
    <p>${escapeHtml(message)}</p>
    ${!cancelled && itemExists && canCancel ? `<div class="warning-box">${escapeHtml(warningMessage)}</div>` : ''}
    ${detailHtml ? `<section class="details">${detailHtml}</section>` : ''}
    ${actionHtml}
  </main>
</body>
</html>`;
return [{ json: { ...row, response_code: responseCode, html } }];
